.chapter-scope {
  --ink: #2c3e50;
  --muted: #7f8c8d;
  --accent: #00CED1;
  --warm: #FFBF00;
  --line: #ecf0f1;
  --paper: #ffffff;
  font-family: system-ui, -apple-system, sans-serif;
  color: var(--ink);
  background: var(--paper);
  padding: 2rem;
  line-height: 1.6;
}

.chapter-scope h2 {
  font-size: 1.8rem;
  margin-bottom: 0.5rem;
  color: var(--ink);
  border-bottom: 2px solid var(--accent);
  padding-bottom: 0.5rem;
}

.section-summary {
  font-size: 1.1rem;
  color: var(--muted);
  margin-bottom: 2rem;
}

.content-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 2rem;
  margin-bottom: 2rem;
}

@media (max-width: 768px) {
  .content-grid {
    grid-template-columns: 1fr;
  }
}

.main-text p {
  margin-bottom: 1rem;
  font-size: 1rem;
}

.source-btn {
  background: none;
  border: 1px solid var(--muted);
  color: var(--muted);
  padding: 0.2rem 0.5rem;
  font-size: 0.8rem;
  cursor: pointer;
  margin-right: 0.3rem;
  border-radius: 3px;
}

.source-btn:hover {
  border-color: var(--accent);
  color: var(--accent);
}

.interactive-panel {
  background: #f8f9fa;
  padding: 1.5rem;
  border-radius: 8px;
  border: 1px solid var(--line);
}

.control-group {
  margin-bottom: 1rem;
}

.control-group label {
  display: block;
  font-size: 0.9rem;
  margin-bottom: 0.5rem;
  color: var(--ink);
}

#noise-slider {
  width: 100%;
  cursor: pointer;
}

.chart-container {
  position: relative;
  margin-bottom: 1rem;
  background: white;
  border: 1px solid var(--line);
  border-radius: 4px;
}

#cov-chart {
  width: 100%;
  height: auto;
  display: block;
}

.chart-legend {
  display: flex;
  gap: 1rem;
  font-size: 0.8rem;
  margin-top: 0.5rem;
  flex-wrap: wrap;
}

.legend-item {
  display: flex;
  align-items: center;
  gap: 0.3rem;
}

.dot {
  width: 10px;
  height: 10px;
  display: inline-block;
}

.dot.solid {
  background: var(--accent);
}

.dot.dashed {
  border-top: 2px dashed var(--warm);
  background: transparent;
}

.dot.scatter {
  background: var(--ink);
  border-radius: 50%;
}

.data-table-wrapper {
  overflow-x: auto;
  margin-bottom: 1rem;
}

.data-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.85rem;
}

.data-table th, .data-table td {
  border: 1px solid var(--line);
  padding: 0.4rem;
  text-align: right;
}

.data-table th {
  background: #f1f3f5;
  text-align: center;
}

.table-note {
  font-size: 0.75rem;
  color: var(--muted);
  margin-top: 0.5rem;
}

.formula-block {
  background: white;
  padding: 1rem;
  border-left: 3px solid var(--accent);
  margin-top: 1rem;
}

.formula-display {
  font-family: 'Times New Roman', serif;
  font-style: italic;
  font-size: 1.1rem;
  text-align: center;
  margin-bottom: 0.5rem;
}

.formula-note {
  font-size: 0.8rem;
  color: var(--muted);
  text-align: center;
}

.evidence-section h3 {
  font-size: 1.4rem;
  margin-bottom: 1rem;
  color: var(--ink);
}

.claim-card {
  background: white;
  border: 1px solid var(--line);
  padding: 1rem;
  margin-bottom: 1rem;
  border-radius: 6px;
}

.claim-card h4 {
  font-size: 1.1rem;
  margin-bottom: 0.5rem;
  color: var(--ink);
}

.conditions-list {
  font-size: 0.9rem;
  color: var(--muted);
  margin: 0.5rem 0;
  padding-left: 1.2rem;
}

.sources-row {
  margin-top: 0.5rem;
}

@media (prefers-reduced-motion: reduce) {
  #noise-slider {
    transition: none;
  }
}

