(function() {
  'use strict';

  // 1. 数据准备 (从 window.paperMindData.tables 读取，不伪造)
  const tables = window.paperMindData?.tables || [];
  const tableI = tables.find(t => t.id === 'p8-TABLE_1');

  // 提取 Table I 数据用于散点图 (M=9 列作为示例，因为 M 变化时图表轴需固定，这里演示单点变化或固定 M 下的噪声变化)
  // 注意：原表是固定噪声 (0.001/c^2) 下不同 M 的 MSE。为了演示“噪声水平”滑动条的效果，我们需要基于理论公式计算曲线，
  // 并将表中的点作为特定噪声水平下的验证点 (Validation Points)。
  // 教学假设：MSE 与噪声方差 sigma^2 成正比 (在小误差区)。
  // 表中数据对应 sigma_ref = 0.001 (归一化后)。
  // 我们将绘制：MSE(sigma) = MSE_table * (sigma / sigma_ref)

  const sigmaRef = 0.001;
  const mValues = ['M = 4', 'M = 5', 'M = 6', 'M = 7', 'M = 8', 'M = 9', 'M = 10'];

  // 提取 Row E (Theoretical CRLB) 作为基准
  const rowE = tableI?.rows.find(r => r.label === 'E');
  const crlbBase = {};
  if (rowE) {
    mValues.forEach(m => {
      const val = rowE.values[m];
      crlbBase[m] = (val !== 'no sol.' && val !== null) ? parseFloat(val) : null;
    });
  }

  // 提取 Row C (Proposed Method Simulated) 作为仿真点
  const rowC = tableI?.rows.find(r => r.label === 'C');
  const simBase = {};
  if (rowC) {
    mValues.forEach(m => {
      const val = rowC.values[m];
      simBase[m] = (val !== 'no sol.' && val !== null) ? parseFloat(val) : null;
    });
  }

  // 2. DOM 元素
  const slider = document.getElementById('noise-slider');
  const noiseValDisplay = document.getElementById('noise-val');
  const canvas = document.getElementById('cov-chart');
  const ctx = canvas.getContext('2d');
  const tableBody = document.getElementById('table-body');

  // 3. 初始化表格
  function initTable() {
    if (!tableI) return;
    const rowsToRender = ['C', 'E']; // 只渲染 Proposed 和 CRLB 以便对比
    rowsToRender.forEach(label => {
      const row = tableI.rows.find(r => r.label === label);
      if (!row) return;
      const tr = document.createElement('tr');

      const th = document.createElement('th');
      th.textContent = label === 'E' ? 'E (CRLB)' : 'C (Proposed)';
      th.style.textAlign = 'left';
      tr.appendChild(th);

      mValues.forEach(m => {
        const td = document.createElement('td');
        td.textContent = row.values[m];
        tr.appendChild(td);
      });
      tableBody.appendChild(tr);
    });
  }

  // 4. 绘图逻辑
  function drawChart(currentSigma) {
    if (!ctx || !crlbBase) return;

    // 清空画布
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    const width = canvas.width;
    const height = canvas.height;
    const padding = 40;
    const plotW = width - padding * 2;
    const plotH = height - padding * 2;

    // 坐标轴设置
    // X 轴：M 值 (分类)，映射为 0..6
    // Y 轴：MSE (对数或线性，这里用线性，因为范围在 0.09 - 0.7 左右)
    // 动态缩放 Y 轴以适应当前噪声水平
    const maxMSE = Math.max(...Object.values(crlbBase).filter(v => v !== null)) * (currentSigma / sigmaRef) * 1.2;
    const minMSE = 0;

    // 绘制坐标轴
    ctx.beginPath();
    ctx.strokeStyle = '#7f8c8d';
    ctx.lineWidth = 1;
    ctx.moveTo(padding, padding);
    ctx.lineTo(padding, height - padding);
    ctx.lineTo(width - padding, height - padding);
    ctx.stroke();

    // 绘制 Y 轴标签
    ctx.fillStyle = '#7f8c8d';
    ctx.font = '10px sans-serif';
    ctx.textAlign = 'right';
    ctx.fillText(maxMSE.toFixed(3), padding - 5, padding + 5);
    ctx.fillText('0', padding - 5, height - padding);
    ctx.save();
    ctx.translate(15, height / 2);
    ctx.rotate(-Math.PI / 2);
    ctx.fillText('MSE (Variance)', 0, 0);
    ctx.restore();

    // 辅助函数：坐标映射
    const getX = (index) => padding + (index / (mValues.length - 1)) * plotW;
    const getY = (val) => height - padding - (val / maxMSE) * plotH;

    // 绘制 CRLB 曲线 (虚线)
    ctx.beginPath();
    ctx.strokeStyle = '#FFBF00'; // warm
    ctx.lineWidth = 2;
    ctx.setLineDash([5, 3]);
    let first = true;
    mValues.forEach((m, i) => {
      const baseVal = crlbBase[m];
      if (baseVal === null) return;
      const scaledVal = baseVal * (currentSigma / sigmaRef);
      const x = getX(i);
      const y = getY(scaledVal);
      if (first) { ctx.moveTo(x, y); first = false; }
      else { ctx.lineTo(x, y); }
    });
    ctx.stroke();
    ctx.setLineDash([]);

    // 绘制 理论协方差 (实线，理论上应与 CRLB 重合)
    ctx.beginPath();
    ctx.strokeStyle = '#00CED1'; // accent
    ctx.lineWidth = 2;
    first = true;
    mValues.forEach((m, i) => {
      const baseVal = crlbBase[m]; // 假设理论推导结果等于 CRLB
      if (baseVal === null) return;
      const scaledVal = baseVal * (currentSigma / sigmaRef);
      const x = getX(i);
      const y = getY(scaledVal);
      if (first) { ctx.moveTo(x, y); first = false; }
      else { ctx.lineTo(x, y); }
    });
    ctx.stroke();

    // 绘制 仿真 MSE 点 (散点)
    mValues.forEach((m, i) => {
      const baseVal = simBase[m];
      if (baseVal === null) return;
      const scaledVal = baseVal * (currentSigma / sigmaRef);
      const x = getX(i);
      const y = getY(scaledVal);

      ctx.beginPath();
      ctx.fillStyle = '#2c3e50'; // ink
      ctx.arc(x, y, 4, 0, Math.PI * 2);
      ctx.fill();
    });

    // 绘制 X 轴标签
    ctx.textAlign = 'center';
    mValues.forEach((m, i) => {
      const x = getX(i);
      ctx.fillText(m.replace('M = ', ''), x, height - padding + 15);
    });
  }

  // 5. 事件监听
  slider.addEventListener('input', (e) => {
    const val = parseFloat(e.target.value);
    noiseValDisplay.textContent = val.toFixed(4);
    drawChart(val);
  });

  // 6. 初始化
  initTable();
  drawChart(parseFloat(slider.value));

})();
